  const toggleSpeech = () => {
    if (isPlaying) {
      stopSpeech();
    } else if (currentScenario) {
      // Resume speech for current scenario
      startSpeech(currentScenario, currentMode);
    }
  };

  // Function to change scenario
  const changeScenario = (scenario: string, mode: 'normal' | 'escalation' = 'normal') => {
    if (isPlaying) {
      startSpeech(scenario, mode);
    } else {
      setCurrentScenario(scenario);
      setCurrentMode(mode);
    }
  };

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      forceStopSpeech();
    };
  }, []);

  return {
    isPlaying,
    currentScenario,
    currentMode,
    startSpeech,
    stopSpeech,
    toggleSpeech,
    changeScenario,
    forceStopSpeech
  };
};
